import type { Metadata } from "next";
import { getTool, getToolPath } from "./tools";
import { siteAuthor, siteName, siteUrl } from "./site";

// One image per page, generated by scripts/og/generate-og-images.py into public/og/.
export function ogImageFor(path: string, alt: string) {
  const key = path.replace(/^\/+|\/+$/g, "").replace(/\//g, "--") || "home";
  return { url: `/og/${key}.png`, width: 1200, height: 630, alt };
}

// Google cuts titles at roughly 60 characters. Add "| SolveGrid" only when the whole title still fits,
// so the keyword-rich part is never truncated. Google shows the site name above the link anyway.
export function withBrandIfFits(title: string) {
  if (title.includes(siteName)) return title;
  const branded = `${title} | ${siteName}`;
  return branded.length <= 60 ? branded : title;
}

const sharedMetadata: Pick<Metadata, "authors" | "creator" | "publisher"> = {
  authors: [{ name: siteAuthor.name, url: `${siteUrl}/about` }],
  creator: siteName,
  publisher: siteName,
};

export function createToolMetadata(slug: string): Metadata {
  const tool = getTool(slug);
  const canonicalPath = getToolPath(tool);
  const ogImage = ogImageFor(canonicalPath, `${tool.name} – SolveGrid`);
  const serpTitle = withBrandIfFits(tool.title);

  return {
    ...sharedMetadata,
    title: { absolute: serpTitle },
    description: tool.description,
    keywords: tool.keywords,
    alternates: {
      canonical: canonicalPath,
    },
    openGraph: {
      type: "website",
      siteName,
      locale: "en_US",
      title: serpTitle,
      description: tool.description,
      url: canonicalPath,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: serpTitle,
      description: tool.description,
      images: [ogImage.url],
    },
    robots: {
      index: true,
      follow: true,
    },
    other: {
      "application-name": siteName,
      "x-solvegrid-url": `${siteUrl}${canonicalPath}`,
    },
  };
}

export function createStaticPageMetadata(
  title: string,
  description: string,
  canonicalPath: string,
): Metadata {
  const ogImage = ogImageFor(canonicalPath, `${title} – SolveGrid`);
  const fullTitle = withBrandIfFits(title);
  return {
    ...sharedMetadata,
    title: { absolute: fullTitle },
    description,
    alternates: { canonical: canonicalPath },
    openGraph: {
      type: "website",
      siteName,
      locale: "en_US",
      title: fullTitle,
      description,
      url: canonicalPath,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage.url],
    },
    robots: {
      index: true,
      follow: true,
    },
  };
}
